refused_program.body:
set -e
git fetch --quiet {upstream_remote} || true
git merge --no-edit {upstream_remote}/{upstream_branch} || true
if git ls-files -u | grep -q .; then
  tmp=$(mktemp -d)
  trap 'rm -rf "$tmp"' EXIT
  mb=$(git merge-base HEAD MERGE_HEAD)
  git diff --name-only --diff-filter=U -z | tr '\0' '\n' > "$tmp/conflicted"
  cat > "$tmp/merge.awk" <<'AWK'
function key(s,   p, q, r) {
  p = index(s, "=")
  if (p > 1) {
    r = substr(s, 1, p - 1)
    sub(/^[ \t]+/, "", r)
    sub(/[ \t]+$/, "", r)
    if (r != "") return "K:" r
  }
  q = index(s, "\"")
  if (q > 0) {
    r = substr(s, q + 1)
    p = index(r, "\"")
    if (p > 1) {
      r = substr(r, 1, p - 1)
      sub(/[ \t].*$/, "", r)
      if (r != "") return "Q:" r
    }
  }
  return ""
}
FNR == 1 { file++ }
file == 1 { base[$0] = 1; bk[key($0)] = 1; next }
file == 2 { n++; ours[n] = $0; ok[n] = key($0); oset[$0] = 1; next }
file == 3 { m++; th[m] = $0; next }
END {
  for (i = 1; i <= m; i++) {
    s = th[i]
    if (s in base) continue
    if (s in oset) continue
    k = key(s)
    repl = 0
    if (k != "") {
      for (j = 1; j <= n; j++) {
        if (ok[j] == k) {
          ours[j] = s
          oset[s] = 1
          repl = 1
          break
        }
      }
    }
    if (repl) continue
    if (k != "" && (k in bk)) continue
    anchor = 0
    for (p = i + 1; p <= m && anchor == 0; p++) {
      if (th[p] in oset) {
        for (j = 1; j <= n; j++) {
          if (ours[j] == th[p]) {
            anchor = j
            break
          }
        }
      }
    }
    if (anchor > 0) {
      if (anchor in ins) {
        ins[anchor] = ins[anchor] SUBSEP s
      } else {
        ins[anchor] = s
      }
    } else {
      if (tail == "") {
        tail = s
      } else {
        tail = tail SUBSEP s
      }
    }
  }
  for (j = 1; j <= n; j++) {
    if (j in ins) {
      c = split(ins[j], a, SUBSEP)
      for (x = 1; x <= c; x++) print a[x]
    }
    print ours[j]
  }
  if (tail != "") {
    c = split(tail, a, SUBSEP)
    for (x = 1; x <= c; x++) print a[x]
  }
}
AWK
  while IFS= read -r f; do
    if [ -z "$f" ]; then
      continue
    fi
    if ! git show "HEAD:$f" > "$tmp/ours" 2>/dev/null; then
      git rm -q -f -- "$f" >/dev/null 2>&1 || true
      continue
    fi
    if ! git show "MERGE_HEAD:$f" > "$tmp/theirs" 2>/dev/null; then
      cp "$tmp/ours" "$f"
      git add -- "$f"
      continue
    fi
    if ! git show "$mb:$f" > "$tmp/base" 2>/dev/null; then
      : > "$tmp/base"
    fi
    if [ ! -s "$tmp/base" ]; then
      printf '\001\n' > "$tmp/base"
    fi
    awk -f "$tmp/merge.awk" "$tmp/base" "$tmp/ours" "$tmp/theirs" > "$f"
    git add -- "$f"
  done < "$tmp/conflicted"
  git commit --no-edit
fi
